def enlazar_legado(apps, schema_editor):
    Bloque = apps.get_model("web", "BloqueHorario")
    Solicitud = apps.get_model("web", "Postulacion")
    alias = schema_editor.connection.alias
    for bloque in Bloque.objects.using(alias).all().iterator():
        bloque.referencia = uuid.uuid4()
        solicitud = Solicitud.objects.using(alias).filter(bloque_id=bloque.pk).first()
        estado = bloque.estado.upper()
        if solicitud:
            if solicitud.tatuadora_id != bloque.tatuadora_id:
                raise RuntimeError("Hay una reserva anterior con tatuadora distinta; revisarla antes de migrar.")
            bloque.postulacion_id = solicitud.pk
            bloque.tipo = "CITA"
            bloque.estado = "CANCELADA" if estado in ("CANCELADA", "CANCELADO") else "REALIZADA" if estado == "REALIZADA" else "RESERVADA"
        elif estado in ("DISPONIBLE", "LIBRE"):
            bloque.estado = "DISPONIBLE"
        else:
            bloque.tipo = "BLOQUEO"
            bloque.estado = "CANCELADA" if estado in ("CANCELADA", "CANCELADO") else "BLOQUEADO"
        bloque.save(using=alias)


